function Panel() {
  const [a, setA] = useState(0);
  const [b, setB] = useState(0);
  console.log('render', a, b);
  useEffect(() => {
    setTimeout(() => {
      setA(1);
      setB(1);
    }, 100);
  }, []);
  return null;
}
// Mount 1: ReactDOM.render(<Panel />, el)   — legacy root
// Mount 2: createRoot(el).render(<Panel />) — React 18 root

