function PageView({ path }: { path: string }) {
  useEffect(() => {
    analytics.track('page_view', { path });
  }, [path]);
  return null;
}

function LiveFeed({ room }: { room: string }) {
  const [msgs, setMsgs] = useState<Msg[]>([]);
  useEffect(() => {
    const ws = new WebSocket(`wss://feed/${room}`);
    ws.onmessage = (e) => setMsgs((m) => [...m, JSON.parse(e.data)]);
  }, [room]);
  return <List items={msgs} />;
}
